from functools import wraps
from time import perf_counter

def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = perf_counter()
        result = func(*args, **kwargs)
        print(perf_counter() - start)
        return result
    return wrapper

class Cart:
    def __init__(self):
        self.items = []

    def __len__(self):
        return len(self.items)

def add(a: int, b: int) -> int:
